import customers from './customers.json' with {type:'json'};

const TOOL_DEFINITIONS = [
  {
    name: 'customer_lookup',
    description: 'Look up a customer by their unique identifier and return their profile.',
    inputSchema: {
      type: 'object',
      properties: {
        customer_id: {
          type: 'string',
          description: 'The unique identifier of the customer to look up.'
        }
      },
      required: ['customer_id'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOL_DEFINITIONS;
}

export async function callTool(name, args) {
  const tool = TOOL_DEFINITIONS.find(t => t.name === name);
  if (!tool) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error(`Invalid arguments for ${name}: expected a JSON object`);
  }

  const allowedKeys = Object.keys(tool.inputSchema.properties);
  const providedKeys = Object.keys(args);
  const unknownKeys = providedKeys.filter(k => !allowedKeys.includes(k));
  if (unknownKeys.length > 0) {
    throw new Error(
      `Invalid arguments for ${name}: unknown field(s): ${unknownKeys.join(', ')}`
    );
  }

  for (const requiredKey of tool.inputSchema.required) {
    const value = args[requiredKey];
    if (value === undefined || value === null) {
      throw new Error(
        `Invalid arguments for ${name}: missing required field '${requiredKey}'`
      );
    }
    const expectedType = tool.inputSchema.properties[requiredKey].type;
    if (expectedType === 'string' && typeof value !== 'string') {
      throw new Error(
        `Invalid arguments for ${name}: '${requiredKey}' must be a string`
      );
    }
    if (expectedType === 'string' && value.length === 0) {
      throw new Error(
        `Invalid arguments for ${name}: '${requiredKey}' must be a non-empty string`
      );
    }
  }

  const { customer_id } = args;
  const customer = customers[customer_id];
  if (!customer) {
    throw new Error(`Unknown customer: ${customer_id}`);
  }

  const text = `Customer ${customer_id}: ${customer.name} (${customer.tier} tier)`;
  return { content: [{ type: 'text', text }] };
}

